def write(path, content):
    (OUT / path).write_text(content, encoding='utf-8')

def page(title, body, nested=True, wide=False, active=''):
    rel = '../' if nested else ''
    portal = '../../index.html' if nested else '../index.html'
    nav = [('index.html','Aulas'), ('reference/caderno.html','Meu plano'), ('reference/processo.html','Método'), ('reference/avaliacao.html','Avaliação')]
    links = ''.join(f'<a href="{rel}{href}"'+(' aria-current="page"' if label==active else '')+f'>{label}</a>' for href,label in nav)
    return f'''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Curso prático: conteúdo útil, produção sustentável e confiança nas redes sociais."><title>{escape(title)} | Redes sociais — FBR Training</title><link rel="stylesheet" href="{rel}assets/course.css"><script src="{rel}assets/course.js" defer></script></head>
<body><a class="skip-link" href="#conteudo">Ir para o conteúdo</a><header class="top"><a href="{rel}index.html">RS<span>Como crescer suas redes sociais</span></a><a class="portal-home" href="{portal}">Todos os cursos</a><a href="{rel}reference/caderno.html">Meu plano</a></header><nav class="course-nav" aria-label="Menu do curso">{links}</nav><main id="conteudo" class="{'wide' if wide else 'reading'}">{body}</main><footer>FBR Training • Como crescer suas redes sociais • Edição 15/10/2026<br>Base: transcrição fornecida pelo usuário. Casos e números fictícios para prática.<br><button class="quiet" type="button" onclick="window.print()">Imprimir / salvar em PDF</button></footer></body></html>'''

def quiz(key, question, choices, feedback, correct_position):
    # A alternativa correta entra em posições alternadas. Cada opção tem o mesmo número de palavras.
    assert len({len(x.split()) for x in choices}) == 1, (key, choices)
    buttons = ''.join(f'<button type="button" data-choice="{i}" aria-pressed="false">{escape(c)}</button>' for i,c in enumerate(choices))
    return f'<div class="quiz" data-correct="{correct_position}" data-key="{key}" data-feedback="{escape(feedback, quote=True)}"><h3>{question}</h3><div class="choices">{buttons}</div><p class="feedback" role="status" aria-live="polite"></p></div>'

manifest=[]
for i, lesson in enumerate(LESSONS, 1):
    title, slug, goal, explanation, case, steps, deliverable, question, choices, feedback = lesson
    module = (i-1)//3+1
    file = f'{i:04d}-{slug}.html'
    manifest.append(dict(number=i,title=title,file=file,module=module))
    paragraphs=''.join(f'<p>{p}</p>' for p in explanation.split('|'))
    source = '<p><a href="../reference/fontes.html#transcricao">Fonte principal: transcrição analisada e limites de interpretação →</a></p>'
    if i in (13,16):
        source += '<p><a href="https://support.google.com/youtube/answer/9314415?hl=pt-BR" target="_blank" rel="noopener">YouTube: momentos importantes da retenção de público ↗</a> · <a href="https://developers.google.com/youtube/analytics/metrics" target="_blank" rel="noopener">Definições oficiais de métricas ↗</a></p>'
    previous = f'{i-1:04d}-{LESSONS[i-2][1]}.html' if i>1 else '../index.html'
    following = f'{i+1:04d}-{LESSONS[i][1]}.html' if i<18 else '../reference/avaliacao.html'
    body=f'''<div class="eyebrow">Módulo {module} / {MODULES[module-1]} • Aula {i:02d} de 18</div><h1>{title}</h1><p class="lead">{goal}</p><div class="meta">8–12 min de estudo • prática no seu ritmo</div><section><h2>Entenda e aplique</h2>{paragraphs}</section><section class="case"><h2>O caso de Marina</h2><p>{case}</p></section><section class="practice"><div class="eyebrow">Sua vez</div><h2>Faça agora</h2><ol>{''.join('<li>'+s+'</li>' for s in steps)}</ol><label for="answer">Sua resposta, evidência ou pendência</label><textarea id="answer" data-save="lesson-{i}-answer" placeholder="Aplique ao seu perfil ou use o caso fictício de Marina."></textarea><p><strong>Entrega:</strong> {deliverable}</p><p class="save-note small" role="status">Salvo neste navegador quando o armazenamento está disponível. Exporte no caderno para guardar uma cópia.</p></section><section><h2>Teste de memória</h2><p>Tente responder antes de reler a explicação.</p>{quiz(f'lesson-{i}-quiz',question,choices,feedback,(i-1)%3)}</section><section class="review"><h2>Volte a este ponto</h2><p>Sem consultar, explique como você chegou à entrega: {deliverable.lower()}</p><p>Amanhã, em 7 dias e em 21 dias, tente lembrar e aplique a decisão a outro contexto antes de conferir suas anotações.</p></section><section><h2>Fonte e materiais de consulta</h2>{source}<p><a href="../reference/processo.html">Método dos cinco passos</a> · <a href="../reference/glossario.html">Glossário de consulta</a> · <a href="../reference/caderno.html">Caderno do plano</a></p><p>Volte ao chat e diga: “Na aula {i}, minha dúvida é…”. Compartilhe seu exercício para receber uma revisão.</p><label class="check"><input type="checkbox" data-save="lesson-{i}-done"> Estudei e fiz o exercício desta aula</label><p class="small">Marcação pessoal de estudo; não comprova domínio ou crescimento do perfil.</p></section><nav class="pagination" aria-label="Navegação entre aulas"><a href="{previous}">← {'Aula anterior' if i>1 else 'Visão geral'}</a><a href="{following}">{'Próxima aula' if i<18 else 'Avaliação final'} →</a></nav>'''
    write('lessons/'+file,page(title,body,active='Aulas'))

